  "test_path": "tests/unit/test_span_filter_claude.py",
  "test": "import pytest
from types import SimpleNamespace

from langfuse.span_filter import is_known_llm_instrumentor, is_default_export_span


def _make_span(scope_name: str):
    scope = SimpleNamespace(name=scope_name)
    return SimpleNamespace(instrumentation_scope=scope, attributes=None)


def test_claude_instrumentation_known_llm():
    span = _make_span("opentelemetry.instrumentation.claude")
    assert is_known_llm_instrumentor(span) is True


def test_claude_instrumentation_default_export():
    span = _make_span("opentelemetry.instrumentation.claude")
    assert is_default_export_span(span) is True"
}
